import * as T from 'three';
import {GLTFLoader} from './vendor/loaders/GLTFLoader.js';
import {ranchMaterial} from './tile-materials.js';
const cache=new Map(),loader=new GLTFLoader();
export async function domesticAsset(id,options={}){if(id==='roof'||id==='soil'){let geometry=new T.BoxGeometry(1,1,1);if(id==='roof'&&options.roofShape==='gable'){geometry.dispose();geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute([-.5,0,-.5,.5,0,-.5,0,1,-.5,-.5,0,.5,.5,0,.5,0,1,.5],3));geometry.setIndex([0,2,1,3,4,5,0,1,4,0,4,3,1,2,5,1,5,4,2,0,3,2,3,5]);geometry.computeVertexNormals();geometry=geometry.toNonIndexed();geometry.computeVertexNormals();}const m=new T.Mesh(geometry,ranchMaterial(id==='roof'?(options.roofColor||'#a67c4f'):'#76583c',id==='roof'?'roof':'ground'));m.castShadow=true;return m;}if(!/^[A-Z]{2}-[0-9]{3,4}(?:\.[a-z-]+)?$/.test(id))throw Error('Unsupported asset identifier');if(!cache.has(id))cache.set(id,loader.loadAsync((id.startsWith('CE-')?'/coastal-assets/':id.startsWith('EH-')?'/castle-assets/':'/domestic-assets/')+id+'.glb').then(g=>{if(id.startsWith('EH-')){const ground=[];g.scene.traverse(o=>{if(o.userData.module_id==='EH-008')ground.push(o);});ground.forEach(o=>o.removeFromParent());}g.scene.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;o.userData.sharedGeometry=true;for(const m of Array.isArray(o.material)?o.material:[o.material])m.userData.shared=true;}});return g.scene;}));return (await cache.get(id)).clone(true);}
export async function drawDomesticGroup(group,placement,scale,groundOffset=()=>0){for(const item of placement.items){const model=await domesticAsset(item.asset,item);model.position.set(item.x*scale,(item.y||0)*scale+(item.grounding==='terrain'?groundOffset(item):0),item.z*scale);model.rotation.y=item.angle||0;if(item.size)model.scale.set(...item.size.map(v=>v*scale));else model.scale.setScalar(scale);model.userData.purpose=item.purpose;group.add(model);}}
